        void DrawNavigation()
        {
            using(new EditorGUILayout.VerticalScope(EditorStyles.helpBox,GUILayout.Width(218)))
            {
                toolSearch=EditorGUILayout.TextField("Find Tool",toolSearch);
                navScroll=EditorGUILayout.BeginScrollView(navScroll);
                DrawNavGroup(0,"OVERVIEW",Tab.Dashboard,Tab.SettingsValidation,Tab.Performance,Tab.Experiments);
                DrawNavGroup(1,"PLAYER",Tab.PlayerBuildLab,Tab.GearCurves,Tab.PassiveOptimizer,Tab.PassiveHeatmap,Tab.ScenarioSweep,Tab.PlayerVsEnemy,Tab.DefenseCalibration);
                DrawNavGroup(2,"ENEMY",Tab.EnemyGearLab,Tab.EnemyAuthoring,Tab.EnemyScaling,Tab.EnemyPreview,Tab.EnemyPower,Tab.BehaviorPreview,Tab.BossPhaseAuthoring);
                DrawNavGroup(3,"LOOT / ITEMIZATION",Tab.WeaponItemLab,Tab.DropSimulator,Tab.ProgressionHistory,Tab.LootProgression,Tab.CraftingSimulator,Tab.AffixAnalyzer);
                DrawNavGroup(4,"COMBAT",Tab.CombatLab,Tab.CombatTimeline,Tab.BatchMatchups,Tab.BossLab,Tab.CombatCurves);
                DrawNavGroup(5,"ANALYSIS",Tab.Sensitivity,Tab.BalanceSnapshots,Tab.BreakpointFinder,Tab.BalanceReport,Tab.CurveExplorer);
                EditorGUILayout.EndScrollView();
            }
