        void DrawNavGroup(int index,string title,params Tab[] members)
        {
            string query=toolSearch?.Trim()??string.Empty;
            bool searching=query.Length>0;
            bool groupMatch=searching&&title.IndexOf(query,StringComparison.OrdinalIgnoreCase)>=0;
            var visible=members.Where(x=>!searching||groupMatch||NavName(x).IndexOf(query,StringComparison.OrdinalIgnoreCase)>=0).ToArray();
            if(visible.Length==0)return;
            if(GUILayout.Button((navOpen[index]||searching?"▾ ":"▸ ")+title,EditorStyles.toolbarButton))navOpen[index]=!navOpen[index];
            if(!navOpen[index]&&!searching)return;
            foreach(Tab member in visible)
            {
                bool selected=tab==member;
                if(GUILayout.Toggle(selected,NavName(member),"Button",GUILayout.Height(24))&&!selected){tab=member;scroll=Vector2.zero;}
            }
        }
        static string NavName(Tab value)=>value switch
        {
            Tab.PassiveOptimizer=>"Passive Optimizer",Tab.PassiveHeatmap=>"Passive Heatmap",
            Tab.DropSimulator=>"Drops / Loot",Tab.LootProgression=>"Loot Progression",Tab.ProgressionHistory=>"Progression History",Tab.DefenseCalibration=>"Defense Calibration",
            Tab.WeaponItemLab=>"Weapon / Item",Tab.SettingsValidation=>"Validation",
            Tab.PlayerBuildLab=>"Player Build",Tab.EnemyGearLab=>"Enemy Gear",
            Tab.CraftingSimulator=>"Crafting Simulator",Tab.AffixAnalyzer=>"Affix Analyzer",
            _=>labels[(int)value]
        };
        static void MetricRow(string label,string value,string unit=null,string delta=null,string state=null)
        {
            using(new EditorGUILayout.HorizontalScope(EditorStyles.helpBox))
            {
                GUILayout.Label(new GUIContent(label,label),EditorStyles.wordWrappedLabel,GUILayout.MinWidth(180),GUILayout.MaxWidth(280),GUILayout.ExpandWidth(true));
                GUILayout.FlexibleSpace();
                float valueWidth=Mathf.Clamp(EditorStyles.boldLabel.CalcSize(new GUIContent(value)).x+8f,105f,240f);
                GUILayout.Label(value,EditorStyles.boldLabel,GUILayout.Width(valueWidth));
                if(!string.IsNullOrEmpty(unit))GUILayout.Label(unit,GUILayout.Width(30));
                if(!string.IsNullOrEmpty(delta))GUILayout.Label(delta,GUILayout.Width(75));
                if(!string.IsNullOrEmpty(state))GUILayout.Label(state,GUILayout.Width(80));
            }
        }
        void DrawHeader(){if(headerCommit==null||EditorApplication.timeSinceStartup>=headerCommitRefresh){headerCommit=ProductionBalanceAdapters.GitCommit();headerCommitRefresh=EditorApplication.timeSinceStartup+30;}using(new EditorGUILayout.HorizontalScope(EditorStyles.toolbar)){GUILayout.Label("BLACK-CUBE BALANCE WORKBENCH",EditorStyles.boldLabel);GUILayout.FlexibleSpace();GUILayout.Label($"Data {ProductionBalanceAdapters.DataFingerprint()}  Git {headerCommit}");}}
