        void Validation()
        {
            Heading("PRODUCTION VALUES");var profile=LootBalanceProfileSO.Current;var so=new SerializedObject(profile);so.Update();EditorGUILayout.PropertyField(so.FindProperty("levelFactorMinimum"));EditorGUILayout.PropertyField(so.FindProperty("levelFactorMaximum"));EditorGUILayout.PropertyField(so.FindProperty("currencyRollCoefficient"));EditorGUILayout.PropertyField(so.FindProperty("extraGearCoefficient"));EditorGUILayout.PropertyField(so.FindProperty("maximumCurrencyRolls"));EditorGUILayout.PropertyField(so.FindProperty("currencies"),true);if(so.hasModifiedProperties){EditorGUILayout.HelpBox("Pending changes are not applied until the explicit button below.",MessageType.Warning);if(GUILayout.Button("APPLY TO PRODUCTION")&&EditorUtility.DisplayDialog("Apply loot production values?","This writes the authoritative LootBalanceProfile asset. Undo is available.","Apply","Cancel")){Undo.RecordObject(profile,"Apply loot balance values");so.ApplyModifiedProperties();EditorUtility.SetDirty(profile);AssetDatabase.SaveAssets();status="Production loot profile updated.";}}
            Heading("VALIDATION");if(GUILayout.Button("VALIDATE BALANCE TOOLING")){string[] errors=BalanceWorkbenchValidation.Validate();status=errors.Length==0?"PASS: all balance tooling adapters validated.":string.Join(" | ",errors);EditorUtility.DisplayDialog(errors.Length==0?"Validation Passed":"Validation Failed",status,"OK");}EditorGUILayout.LabelField("Production RNG",LootRandomSourceFactory.CreateProduction().GetType().Name);EditorGUILayout.LabelField("Save schema",GamePersistence.SchemaVersion.ToString());EditorGUILayout.LabelField("Data fingerprint",ProductionBalanceAdapters.DataFingerprint());Heading("FUTURE EXTENSION POINTS");GUILayout.Label("Player Builds · Passive Optimizer · Enemy Authoring · Combat Lab · Sensitivity · Affix Analyzer · Crafting · Regression · Breakpoints",EditorStyles.wordWrappedLabel);
        }
        string lastOperation="None";double lastElapsedMs,lastRepaintMs,repaintTotalMs;long repaintSampleCount;int lastGen0,lastGen1,lastGen2;long lastCacheHits,lastCacheMisses,lastReusedEvaluations;bool lastCancelled,lastFailed;
        void Run(string title,Action<float> action){cancelled=false;lastFailed=false;int g0=GC.CollectionCount(0),g1=GC.CollectionCount(1),g2=GC.CollectionCount(2);long hits=PlayerBuildEvaluator.CacheHits,misses=PlayerBuildEvaluator.CacheMisses,reused=PlayerBuildEvaluation.ReusedEvaluationCount;var timer=Stopwatch.StartNew();try{action(0);status=cancelled?"Simulation cancelled; partial result retained.":title+" complete.";}catch(Exception ex){lastFailed=true;status=ex.Message;Debug.LogException(ex);}finally{timer.Stop();lastOperation=title;lastElapsedMs=timer.Elapsed.TotalMilliseconds;lastGen0=GC.CollectionCount(0)-g0;lastGen1=GC.CollectionCount(1)-g1;lastGen2=GC.CollectionCount(2)-g2;lastCacheHits=PlayerBuildEvaluator.CacheHits-hits;lastCacheMisses=PlayerBuildEvaluator.CacheMisses-misses;lastReusedEvaluations=PlayerBuildEvaluation.ReusedEvaluationCount-reused;lastCancelled=cancelled;EditorUtility.ClearProgressBar();Repaint();}}
        void PerformanceTab(){Heading("WORKBENCH UI");EditorGUILayout.LabelField("Last repaint",$"{lastRepaintMs:0.###} ms");EditorGUILayout.LabelField("Average repaint",$"{repaintTotalMs/Math.Max(1,repaintSampleCount):0.###} ms across {repaintSampleCount} samples");EditorGUILayout.LabelField("Reused-actor evaluations",lastReusedEvaluations.ToString());if(lastFailed)EditorGUILayout.HelpBox("Last operation failed: "+status,MessageType.Error);DrawPerformanceOperations();}
        void DrawPerformanceOperations(){Heading("LAST WORKBENCH OPERATION");EditorGUILayout.LabelField("Operation",lastOperation);EditorGUILayout.LabelField("Status",lastCancelled?"Cancelled":"Completed");EditorGUILayout.LabelField("Elapsed",$"{lastElapsedMs:0.###} ms");EditorGUILayout.LabelField("GC collections",$"Gen0 {lastGen0} · Gen1 {lastGen1} · Gen2 {lastGen2}");EditorGUILayout.LabelField("Build evaluations",(lastCacheHits+lastCacheMisses).ToString());EditorGUILayout.LabelField("Build cache",$"Hits {lastCacheHits} · misses {lastCacheMisses} · entries {PlayerBuildEvaluator.CacheEntries}");if(passiveResult?.debug?.Count>0){Heading("PASSIVE SEARCH COUNTERS");int attempts=passiveResult.debug.Sum(x=>x.candidateStates),unique=passiveResult.debug.Sum(x=>x.statesEvaluated);EditorGUILayout.LabelField("Candidate attempts",attempts.ToString());EditorGUILayout.LabelField("Unique states evaluated",unique.ToString());EditorGUILayout.LabelField("Duplicate allocations skipped",(attempts-unique).ToString());EditorGUILayout.LabelField("Peak candidates / depth",passiveResult.debug.Max(x=>x.candidateStates).ToString());EditorGUILayout.LabelField("Final retained",passiveResult.debug[^1].retainedStates.ToString());EditorGUILayout.LabelField("Final depth",passiveResult.debug[^1].depth.ToString());EditorGUILayout.LabelField("Evaluations / second",(unique/Math.Max(.001,lastElapsedMs/1000)).ToString("0.##"));}if(GUILayout.Button("EXPORT PERFORMANCE REPORT")){Directory.CreateDirectory(WorkbenchExports.Root);string path=Path.Combine(WorkbenchExports.Root,"workbench_performance_"+DateTime.UtcNow.ToString("yyyyMMdd_HHmmss")+".csv");int states=passiveResult?.debug?.Sum(x=>x.statesEvaluated)??0;string csv="Operation,ElapsedMs,States,CacheHits,CacheMisses,Gen0,Gen1,Gen2,Fingerprint,GitCommit,Cancelled\n"+string.Join(",",new[]{lastOperation,lastElapsedMs.ToString("R",System.Globalization.CultureInfo.InvariantCulture),states.ToString(),lastCacheHits.ToString(),lastCacheMisses.ToString(),lastGen0.ToString(),lastGen1.ToString(),lastGen2.ToString(),ProductionBalanceAdapters.DataFingerprint(),headerCommit,lastCancelled.ToString()});File.WriteAllText(path,csv);status="Exported "+path;}Heading("BENCHMARK REPORTS");foreach(string phase in new[]{"baseline_core","baseline_passive","after_core","after_passive"}){string path=$"Logs/BalanceWorkbenchPerformance/{phase}.json";if(!File.Exists(path))continue;var report=JsonUtility.FromJson<WorkbenchPerformanceReport>(File.ReadAllText(path));Heading(phase);foreach(var row in report.rows)EditorGUILayout.LabelField(row.operation,$"{row.elapsedMs:0.###} ms · {row.evaluations} evaluations · {row.resultHash}");}EditorGUILayout.HelpBox("Benchmark reports are written by the explicit batchmode runner, not by opening this tab. Times vary by machine and Editor state; compare matching result hashes first.",MessageType.Info);}
        Action<float> Progress(string label)=>p=>{if(EditorUtility.DisplayCancelableProgressBar("Black-Cube Balance Workbench",$"{label}: {p:P1}",p))cancelled=true;};
        static int SampleCount(int value,int max=10000){using(new EditorGUILayout.HorizontalScope()){value=EditorGUILayout.IntField("Sample Count",value);if(GUILayout.Button("100",GUILayout.Width(48)))value=100;if(GUILayout.Button("1,000",GUILayout.Width(52)))value=1000;if(GUILayout.Button("10,000",GUILayout.Width(58)))value=10000;}return Mathf.Clamp(value,1,max);}
        void SweepInputs(int max,bool showSamples=true){using(new EditorGUILayout.HorizontalScope()){sweepStart=EditorGUILayout.IntField("Sweep Start",sweepStart);sweepEnd=EditorGUILayout.IntField("End",sweepEnd);sweepIncrement=EditorGUILayout.IntField("Step",sweepIncrement);if(showSamples)sweepSamples=EditorGUILayout.IntField("Samples / Level",sweepSamples);}sweepStart=Mathf.Clamp(sweepStart,1,max);sweepEnd=Mathf.Clamp(sweepEnd,sweepStart,max);sweepIncrement=Mathf.Max(1,sweepIncrement);sweepSamples=Mathf.Clamp(sweepSamples,1,10000);}
        void RunItemSweep(){cancelled=false;var mean=new CurveSeries{name="Mean",color=Color.cyan};var p10=new CurveSeries{name="P10",color=Color.gray};var p50=new CurveSeries{name="P50",color=Color.green};var p90=new CurveSeries{name="P90",color=Color.yellow};int original=item.itemLevel,count=item.sampleCount;try{item.sampleCount=sweepSamples;for(int l=sweepStart;l<=sweepEnd&&!cancelled;l+=sweepIncrement){item.itemLevel=l;var r=ProductionBalanceAdapters.RunItems(item);mean.points.Add(new CurvePoint{x=l,mean=r.weaponDps.mean});p10.points.Add(new CurvePoint{x=l,mean=r.weaponDps.p10});p50.points.Add(new CurvePoint{x=l,mean=r.weaponDps.p50});p90.points.Add(new CurvePoint{x=l,mean=r.weaponDps.p90});cancelled=EditorUtility.DisplayCancelableProgressBar("Item Level Sweep",$"Level {l}",(l-sweepStart+1f)/(sweepEnd-sweepStart+1f));}curves=new(){mean,p10,p50,p90};tab=Tab.CurveExplorer;status="Item DPS level sweep complete.";}finally{item.itemLevel=original;item.sampleCount=count;EditorUtility.ClearProgressBar();}}
        void RunEnemySweep(){cancelled=false;var life=new CurveSeries{name="Enemy P50 Life",color=Color.green};var dps=new CurveSeries{name="Enemy P50 DPS",color=Color.red};var p90=new CurveSeries{name="Enemy P90 DPS",color=Color.yellow};int original=enemy.level,count=enemy.sampleCount;try{enemy.sampleCount=sweepSamples;for(int l=sweepStart;l<=sweepEnd&&!cancelled;l+=sweepIncrement){enemy.level=l;var r=ProductionBalanceAdapters.RunEnemies(enemy);life.points.Add(new CurvePoint{x=l,mean=r.life.p50});dps.points.Add(new CurvePoint{x=l,mean=r.dps.p50});p90.points.Add(new CurvePoint{x=l,mean=r.dps.p90});cancelled=EditorUtility.DisplayCancelableProgressBar("Enemy Gear Sweep",$"Level {l}",(l-sweepStart+1f)/(sweepEnd-sweepStart+1f));}curves=new(){life,dps,p90};tab=Tab.CurveExplorer;status="Enemy gear level sweep complete.";}finally{enemy.level=original;enemy.sampleCount=count;EditorUtility.ClearProgressBar();}}
        void RunDropSweep(){cancelled=false;var chance=new CurveSeries{name="Any Currency Chance",color=Color.cyan};var rolls=new CurveSeries{name="Currency Rolls / Kill",color=Color.yellow};int original=drop.level,count=drop.sampleCount;try{drop.sampleCount=sweepSamples;for(int l=sweepStart;l<=sweepEnd&&!cancelled;l+=sweepIncrement){drop.level=l;var r=ProductionBalanceAdapters.RunDrops(drop);chance.points.Add(new CurvePoint{x=l,mean=r.chanceAnyCurrency});rolls.points.Add(new CurvePoint{x=l,mean=r.averageCurrencyRolls});cancelled=EditorUtility.DisplayCancelableProgressBar("Drop Sweep",$"Level {l}",(l-sweepStart+1f)/(sweepEnd-sweepStart+1f));}curves=new(){chance,rolls};tab=Tab.CurveExplorer;status="Drop level sweep complete.";}finally{drop.level=original;drop.sampleCount=count;EditorUtility.ClearProgressBar();}}
        void RunRarityMatrix(){dropMatrix.Clear();var original=drop.rarity;bool boss=drop.boss;try{foreach(EnemyAI.EnemyRarity rarity in Enum.GetValues(typeof(EnemyAI.EnemyRarity))){drop.rarity=rarity;drop.boss=false;var r=ProductionBalanceAdapters.RunDrops(drop);r.metadata.scenario=rarity.ToString();dropMatrix.Add(r);}drop.rarity=EnemyAI.EnemyRarity.Legendary;drop.boss=true;var br=ProductionBalanceAdapters.RunDrops(drop);br.metadata.scenario="Boss";dropMatrix.Add(br);status="Rarity matrix complete.";}finally{drop.rarity=original;drop.boss=boss;}}
        static void Summary(string label,MetricSummary m){if(m==null)return;EditorGUILayout.LabelField(label,$"Mean {m.mean:0.###}  P10 {m.p10:0.###}  P25 {m.p25:0.###}  P50 {m.p50:0.###}  P75 {m.p75:0.###}  P90 {m.p90:0.###}  P95 {m.p95:0.###}  P99 {m.p99:0.###}");}
        static T Representative<T>(List<T> list,double p,Func<T,double> f)=>list.OrderBy(f).ElementAt(Mathf.Clamp((int)Math.Round((list.Count-1)*p),0,list.Count-1));
        static void ShowItem(ItemSample x)=>EditorUtility.DisplayDialog($"Representative item #{x.index}",x.detail+$"\nDPS {x.weaponDps:0.###}\nGearScore {x.gearScore:0.###}","Close");
        static void ShowEnemy(EnemySample x)=>EditorUtility.DisplayDialog($"{x.archetype} L{x.level}",$"Rarity {(EnemyAI.EnemyRarity)x.rarity}\nPrimary {x.primaryDamage}\nLife {x.life:0.##}\nHit {x.damagePerHit:0.##} @ {x.attackSpeed:0.###} APS\nDPS {x.dps:0.##}\nGearScore {x.gearScore:0.##}\nSlots {x.slotCount}; candidates/slot {x.candidateCount}\n{x.equipment}","Close");
        static void DrawHistogram(string label,IEnumerable<double> values){Heading(label);var bins=WorkbenchStatistics.Histogram(values);int max=bins.Count==0?1:bins.Max(x=>x.count);foreach(var b in bins){Rect r=GUILayoutUtility.GetRect(40,12,GUILayout.ExpandWidth(true));EditorGUI.ProgressBar(r,b.count/(float)max,$"{b.minimum:0.#}–{b.maximum:0.#}: {b.count}");}}
        void SavePreset(){Directory.CreateDirectory("Assets/Balance/Presets");string path=EditorUtility.SaveFilePanelInProject("Save Workbench Preset","BalancePreset","json","Choose a preset name","Assets/Balance/Presets");if(string.IsNullOrEmpty(path))return;File.WriteAllText(path,JsonUtility.ToJson(new Preset{item=item,enemy=enemy,drop=drop,playerBuild=playerBuild,objective=objective,constraints=playerConstraints,passivePoints=passivePoints,passiveBeamWidth=passiveBeamWidth,scenarioPassives=scenarioPassives,scenarioProgressive=scenarioProgressive,scenarioFreeRespec=scenarioFreeRespec,hasCombatLevelPolicy=true,combatLevelPolicy=scenarioCombatLevelPolicy,combatLevelOffset=scenarioCombatLevelOffset,sweepStart=sweepStart,sweepEnd=sweepEnd,sweepIncrement=sweepIncrement,gearProfilePath=AssetDatabase.GetAssetPath(gearProfile)},true));AssetDatabase.Refresh();status="Saved "+path;}
        void LoadPreset(){string path=EditorUtility.OpenFilePanel("Load Workbench Preset",Path.GetFullPath("Assets/Balance/Presets"),"json");if(string.IsNullOrEmpty(path))return;var p=JsonUtility.FromJson<Preset>(File.ReadAllText(path));if(p!=null){item=p.item??item;enemy=p.enemy??enemy;drop=p.drop??drop;playerBuild=p.playerBuild??playerBuild;objective=p.objective??objective;playerConstraints=p.constraints??playerConstraints;passivePoints=p.passivePoints>0?p.passivePoints:passivePoints;passiveBeamWidth=p.passiveBeamWidth>0?p.passiveBeamWidth:passiveBeamWidth;scenarioPassives=p.scenarioPassives;scenarioProgressive=p.scenarioProgressive;scenarioFreeRespec=p.scenarioFreeRespec;scenarioCombatLevelPolicy=p.hasCombatLevelPolicy?p.combatLevelPolicy:CombatLevelSweepPolicy.AdvanceFromStart;scenarioCombatLevelOffset=p.combatLevelOffset;sweepStart=p.sweepStart>0?p.sweepStart:sweepStart;sweepEnd=p.sweepEnd>0?p.sweepEnd:sweepEnd;sweepIncrement=p.sweepIncrement>0?p.sweepIncrement:sweepIncrement;if(!string.IsNullOrEmpty(p.gearProfilePath))gearProfile=AssetDatabase.LoadAssetAtPath<PlayerGearProfileSO>(p.gearProfilePath);playerSweep=null;playerMetrics=null;selectedScenarioInspection=null;contributions.Clear();status="Loaded "+path+(p.hasCombatLevelPolicy?"":" (legacy Combat Level policy: Advance From Start)");}}
        string ChoosePreset(string title)=>EditorUtility.OpenFilePanel(title,Path.GetFullPath("Assets/Balance/Presets"),"json");
        void DuplicatePreset(){string source=ChoosePreset("Duplicate Workbench Preset");if(string.IsNullOrEmpty(source))return;string target=EditorUtility.SaveFilePanelInProject("Duplicate Preset",Path.GetFileNameWithoutExtension(source)+" Copy","json","Choose the duplicate name","Assets/Balance/Presets");if(string.IsNullOrEmpty(target))return;File.Copy(source,target,true);AssetDatabase.Refresh();status="Duplicated preset to "+target;}
        void RenamePreset(){string source=ChoosePreset("Rename Workbench Preset");if(string.IsNullOrEmpty(source))return;string relative="Assets"+source.Replace('\\','/').Split(new[]{"/Assets"},StringSplitOptions.None).Last();string target=EditorUtility.SaveFilePanelInProject("Rename Preset",Path.GetFileNameWithoutExtension(source),"json","Choose the new name","Assets/Balance/Presets");if(string.IsNullOrEmpty(target))return;string error=AssetDatabase.MoveAsset(relative,target);status=string.IsNullOrEmpty(error)?"Renamed preset to "+target:error;}
        void DeletePreset(){string source=ChoosePreset("Delete Workbench Preset");if(string.IsNullOrEmpty(source)||!EditorUtility.DisplayDialog("Delete preset?",source,"Delete","Cancel"))return;string relative="Assets"+source.Replace('\\','/').Split(new[]{"/Assets"},StringSplitOptions.None).Last();status=AssetDatabase.DeleteAsset(relative)?"Deleted "+relative:"Could not delete "+relative;}
        [Serializable] sealed class Preset{public ItemLabRequest item;public EnemyLabRequest enemy;public DropLabRequest drop;public PlayerBuildSnapshot playerBuild;public OptimizationObjective objective;public OptimizationConstraints constraints;public int passivePoints,passiveBeamWidth,sweepStart,sweepEnd,sweepIncrement,combatLevelOffset;public bool scenarioPassives,scenarioProgressive,scenarioFreeRespec,hasCombatLevelPolicy;public CombatLevelSweepPolicy combatLevelPolicy;public string gearProfilePath;}
    }

    public static class BalanceWorkbenchValidation
    {
        public static string[] Validate(){var errors=new List<string>();try{using var s=new WorkbenchSession();if(s.Roller.Database==null)errors.Add("Affix database missing");}catch(Exception e){errors.Add(e.Message);}if(WeaponTypeCatalog.All.Count!=6)errors.Add("Expected six weapon profiles");if(WorldContentCatalog.Reference?.enemyArchetypes?.Count<1)errors.Add("Enemy archetypes missing");try{_ = EnemyScalingProfile.Default;}catch(Exception e){errors.Add(e.Message);}if(LootBalanceProfileSO.Current.currencies.Count==0)errors.Add("Loot config missing currencies");var a=new SeededSimulationRandomSource(17);var b=new SeededSimulationRandomSource(17);for(int i=0;i<32;i++)if(a.Value()!=b.Value()){errors.Add("Simulation RNG is not deterministic");break;}if(LootRandomSourceFactory.CreateProduction() is not ProductionLootRandomSource)errors.Add("Production RNG factory changed");foreach(var s in ProductionBalanceAdapters.IntrinsicCurves(1,360,1).SelectMany(x=>x.points))if(!double.IsFinite(s.mean))errors.Add("Curve contains non-finite value");return errors.Distinct().ToArray();}
    }
}
